-- 70 существующих залов Алматы: названия и адреса взяты из источников.
-- Координаты являются грубой учебной оценкой по району (точность 8 км), не точкой входа.
-- Цены 1Fit не приписываются отдельным залам.
SET search_path = almaty_gym, public;
TRUNCATE TABLE bookings, reviews, payments, memberships, classes, trainers, clients, plans, gym_amenities, gyms RESTART IDENTITY CASCADE;
SELECT setval(pg_get_serial_sequence('almaty_gym.gyms','id'), 70, true);
